responsePreview:
The Terraform configuration below creates an AWS DHCP options set named `pike` that uses Google DNS servers `8.8.8.8` and `8.8.4.4`, then associates it with a VPC.

By default, it creates a new VPC for deployability. To associate the DHCP options with an existing VPC, set the `vpc_id` variable.

```hcl
terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region where resources will be created."
  type        = string
  default     = "us-east-1"
}

variable "vpc_id" {
  description = "Existing VPC ID to associate with the DHCP options. Leave empty to create a new VPC."
  type        = string
  default     = ""
}

variable "vpc_cidr_block" {
  description = "CIDR block for the VPC created when vpc_id is not provided."
  type        = string
  default     = "10.0.0.0/16"
}

resource "aws_vpc" "default" {
  count = var.vpc_id == "" ? 1 : 0

  cidr_block           = var.vpc_cidr_block
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "pike-vpc"
  }
}

